import * as THREE from '../vendor/three.module.js';
import {SIZE,SHOALS,water,movePath} from './battle.js';
export function createBattleScene(container,onTile){const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.setClearColor('#103d47');container.prepend(renderer.domElement);const scene=new THREE.Scene(),camera=new THREE.OrthographicCamera();camera.position.set(0,19,16);camera.lookAt(0,0,0);scene.add(new THREE.HemisphereLight('#f9ead2','#20404b',2.4));const sun=new THREE.DirectionalLight('#ffe2ac',2.6);sun.position.set(-6,12,7);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);Object.assign(sun.shadow.camera,{left:-10,right:10,top:12,bottom:-12});scene.add(sun);const colors={escort:'#83c8df',passenger:'#d8be72',raider1:'#b26058',raider2:'#b26058'},tiles=[],units=new Map(),ghosts=new Map();let current=null,mode='move';const ray=new THREE.Raycaster(),pointer=new THREE.Vector2();
function box(w,h,d,color,parent=scene,x=0,y=0,z=0){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),new THREE.MeshStandardMaterial({color,roughness:.85}));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
for(let z=0;z<SIZE.h;z++)for(let x=0;x<SIZE.w;x++){const legal=water(x,z);const m=box(.96,legal?.08:.4,.96,legal?((x+z)%2?'#256574':'#296d7a'):'#9eab86',scene,x-5.5,legal?-.1:.02,z-7.5);m.userData={x,z};tiles.push(m);if(!legal&&x%2===0&&z%3===0){box(.12,.7,.12,'#665940',scene,x-5.5,.5,z-7.5);const crown=new THREE.Mesh(new THREE.IcosahedronGeometry(.4,0),new THREE.MeshStandardMaterial({color:'#577764'}));crown.position.set(x-5.5,1,z-7.5);scene.add(crown);}}
function ship(id,ghost=false){const g=new THREE.Group();const hull=box(.48,.21,.85,colors[id],g,0,.18,0);box(.34,.06,.62,'#dfc792',g,0,.31,0);box(.055,.8,.055,'#574631',g,0,.7,0);const sail=new THREE.Mesh(new THREE.PlaneGeometry(.54,.56),new THREE.MeshStandardMaterial({color:'#fff0d0',side:THREE.DoubleSide}));sail.position.set(.16,.77,0);g.add(sail);const prow=new THREE.Mesh(new THREE.ConeGeometry(.24,.35,4),hull.material);prow.rotation.x=-Math.PI/2;prow.position.set(0,.18,-.45);g.add(prow);const ring=new THREE.Mesh(new THREE.RingGeometry(.57,.61,32),new THREE.MeshBasicMaterial({color:colors[id],side:THREE.DoubleSide,transparent:true,opacity:ghost?.35:.8}));ring.rotation.x=-Math.PI/2;ring.position.y=.01;g.add(ring);if(ghost)g.traverse(m=>{if(m.material){m.material=m.material.clone();m.material.transparent=true;m.material.opacity=.24;m.material.depthWrite=false;m.castShadow=false;}});scene.add(g);return g;}
for(const id of Object.keys(colors)){units.set(id,ship(id));ghosts.set(id,ship(id,true));}
function draw(s,next,showPreview,activeMode){current=s;mode=activeMode;for(const u of[s.escort,s.passenger,...s.enemies]){const m=units.get(u.id);m.visible=u.hp>0;m.position.set(u.x-5.5,0,u.z-7.5);m.rotation.y={north:0,east:-Math.PI/2,south:Math.PI,west:Math.PI/2}[u.facing];const n=[next.escort,next.passenger,...next.enemies].find(v=>v.id===u.id),ghost=ghosts.get(u.id);ghost.visible=showPreview&&n.hp>0&&(n.x!==u.x||n.z!==u.z);ghost.position.set(n.x-5.5,0,n.z-7.5);}
for(const tile of tiles){const{x,z}=tile.userData;const reachable=activeMode==='move'&&s.status==='playing'&&movePath(s,{x,z})?.length;tile.material.color.set(!water(x,z)?'#9eab86':reachable?'#438e92':z===0?'#789f83':(x+z)%2?'#256574':'#296d7a');}renderer.render(scene,camera);}
function resize(){const r=container.getBoundingClientRect();renderer.setSize(r.width,r.height);const aspect=r.width/r.height,span=Math.max(8.5,6.5/aspect);camera.left=-span*aspect;camera.right=span*aspect;camera.top=span;camera.bottom=-span;camera.near=.1;camera.far=70;camera.updateProjectionMatrix();renderer.render(scene,camera);}
const observer=new ResizeObserver(resize);observer.observe(container);renderer.domElement.addEventListener('pointerdown',e=>{if(e.button!==0)return;const r=renderer.domElement.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(pointer,camera);const hit=ray.intersectObjects(tiles)[0];if(hit)onTile(hit.object.userData);});resize();return{draw,project(u){const v=new THREE.Vector3(u.x-5.5,1.15,u.z-7.5).project(camera),r=container.getBoundingClientRect();return{x:(v.x*.5+.5)*r.width,y:(-.5*v.y+.5)*r.height};},resize};}
